-- ============================================================================
-- 1. EXTEND user_role ENUM WITH 'mentor'
-- ============================================================================
do $$
begin
  if not exists (
    select 1 from pg_enum
    where enumlabel = 'mentor'
      and enumtypid = (select oid from pg_type where typname = 'user_role')
  ) then
    alter type user_role add value 'mentor';
  end if;
end$$;

-- ============================================================================
-- 2. EMPLOYER SPONSORS
