-- 4. Verification query (run manually to confirm)
-- ----------------------------------------------------------------------------
-- select exam_code, title, passing_score,
--   jsonb_array_length(content -> 'questions') as question_count
-- from public.final_exams
-- where exam_code = 'FINAL-COMPREHENSIVE';


